def evaluate(current_reputation, observation, my_history, round_num):
    action = observation['action']

    # Exponential decay weighting for recent actions
    decay = 0.9 ** (round_num / 10)
    recent_factor = 1 - decay

    if action == 'cooperate':
        update = 0.25 * recent_factor
    else:
        update = -0.35 * recent_factor

    # Different smoothing: stronger retention of old reputation
    new_reputation = current_reputation * 0.92 + update * 0.08

    # Clamp between -1 and 1
    new_reputation = max(-1.0, min(1.0, new_reputation))

    return new_reputation

def decide(recipient_reputation, round_num, my_history):
    # Reputation thresholds different from original
    if recipient_reputation > 0.6:
        cooperate_prob = 0.85
    elif recipient_reputation > 0.1:
        cooperate_prob = 0.5 + (recipient_reputation - 0.1) * 1.5
    elif recipient_reputation > -0.4:
        cooperate_prob = 0.25 + (recipient_reputation + 0.4) * 0.5
    else:
        cooperate_prob = 0.1

    # Indirect adjustment based on overall personal history pattern
    if len(my_history) >= 3:
        recent_actions = my_history[-3:]
        recent_coops = sum(1 for h in recent_actions if h.get('action') == 'cooperate')
        if recent_coops >= 2:
            cooperate_prob *= 1.05
        elif recent_coops <= 1:
            cooperate_prob *= 0.95

    cooperate_prob = max(0.05, min(0.95, cooperate_prob))

    return random.random() < cooperate_prob
